export async function updateModerationModule(
  guildId: string,
  botId: string,
  payload: Partial<ModuleModerationSchema>,
): Promise<ModerationUpdateResult> {
  try {
    const modules = db.guilds.modules as unknown as ModulesWithModeration;
    const result = modules.moderation
      ? await modules.moderation.update(
          { guild_id: guildId, bot_id: botId },
          payload,
        )
      : await modules.request(
          "PATCH",
          `/bots/${botId}/guilds/${guildId}/modules/moderation`,
          payload,
        );
    if (result.hasErrors || !result.data) {
      return {
        ok: false,
        errors: result.errors?.map((e) => ({
          message: e.message,
          code: (e as { code?: string }).code,
        })) ?? [{ message: "Unknown error updating moderation module" }],
      };
    }
    return { ok: true, data: result.data as ModuleModerationSchema };
  } catch (err) {
    Logger.error("GUILDS", `updateModerationModule failed for ${guildId}`, err);
    const message = err instanceof Error ? err.message : String(err);
    return { ok: false, errors: [{ message }] };
  }
}
