export const useModerationFeature = () => {
  const dispatch = useAppDispatch();

  const entities = useAppSelector((state) => state.moderation.entities);
  const changed = useAppSelector((state) => state.moderation.changed);
  const previousState = useAppSelector(
    (state) => state.moderation.previousState,
  );

  const data = useMemo(
    () => ({
      module: entities.module.data,
    }),
    [entities],
  );

  const actions = useMemo(
    () => ({
      hydrateSync: (payload: ModerationSyncHydrationPayload) =>
        dispatch(hydrateSync(payload)),
      updateValue: (patch: Partial<ModuleModerationSchema>) =>
        dispatch(updateValue(patch)),
      undoChanges: () => dispatch(undoChanges()),
      setModuleSuccess: (module: ModuleModerationSchema) =>
        dispatch(setModuleSuccess(module)),
      resetModeration: () => dispatch(resetModeration()),
    }),
    [dispatch],
  );

  return {
    data,
    entities,
    changed,
    previousState,
    actions,
  };
};
```

