export async function getModerationModule(
  guildId: string,
  botId: string,
): Promise<ModuleModerationSchema | null> {
  try {
    const { data, hasErrors } = await db.guilds.getModule({
      guild_id: guildId,
      bot_id: botId,
      module: MODERATION_MODULE_KEY,
    });
    if (hasErrors || !data) return null;
    return data as unknown as ModuleModerationSchema;
  } catch (err) {
    Logger.warn("GUILDS", `getModerationModule failed for ${guildId}`, err);
    return null;
  }
}
