559	  categories: DBAccessList;
560	  /** Roles del autor. `all_except` + ids = «roles ignorados». */
561	  roles: DBAccessList;
562	  /** Ignorar autores bot. Nace `true`: es el cortafuegos anti-bucle nº1. */
563	  ignore_bots: boolean;
564	  /** Ignorar a quien tenga ManageMessages/Administrator. Nace `true`. */
565	  ignore_admins: boolean;
566	  /** Cooldown POR USUARIO entre dos ejecuciones. 0 = sin cooldown. */
567	  cooldown_seconds: number;
568	  /** Techo de ejecuciones del flujo por minuto y guild. 0 = sin techo. */
569	  rate_limit_per_minute: number;
570	}
