package handlers

import (
	"strconv"

	"github.com/gofiber/fiber/v3"

	"kena.bot/api-db-go/internal/domain/dbguild"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
	"kena.bot/api-db-go/internal/domain/validations"
	"kena.bot/api-db-go/internal/infrastructure/mongorepo"
	"kena.bot/api-db-go/internal/shared/result"
)

// ModuleGreeterHandler wires the two greeter endpoints behind a single
// struct.
//
// Mirrors `module-greeter-controller.ts` in the Node service.
type ModuleGreeterHandler struct {
	Repo mongorepo.ModuleGreeterRepo
}

// NewModuleGreeterHandler builds the handler.
func NewModuleGreeterHandler(repo mongorepo.ModuleGreeterRepo) *ModuleGreeterHandler {
	return &ModuleGreeterHandler{Repo: repo}
}

// Get mirrors `getModuleGreeterController`. Returns the full greeter
// subdoc (default-filled) with source headers stamped. Honors the
// optional `?force=true` query that evicts the cache before reading.
func (h *ModuleGreeterHandler) Get(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleGreeter]()
	ctx := c.Context()

	force, _ := strconv.ParseBool(c.Query("force"))

	sourced, err := h.Repo.FindModule(ctx, c.Params("bot_id"), c.Params("guild_id"), force)
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		// data:null parity — the Node greeter controller runs
		// applySourceAndStash(sourced{data:null}) before throwing
		// MODULE_NOT_FOUND on both the GET and the update-null PATCH branch.
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))
		return reply(c, r)
	}
	d := sourced.Data
	r.SetData(&d)
	r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	return reply(c, r)
}

// Patch mirrors `patchModuleGreeterController`. Strict body; MergeDeepJSON
// (presence-based) semantics on the server side so partial sub-block updates
// (e.g. `welcome.message.content` only) don't clobber siblings, and explicit
// `false`/`0`/`null` leaves are applied (Node parity).
func (h *ModuleGreeterHandler) Patch(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleGreeter]()
	ctx := c.Context()

	var body validations.UpdateModuleGreeterBody
	if err := c.Bind().Body(&body); err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	// El bind sólo comprueba la FORMA (enums, structs anidados). Los topes de
	// longitud y cardinalidad no existían en ninguna capa del servidor: este
	// endpoint acepta un PATCH directo con la credencial de api-db, y sin esto
	// un `message.content` de 1 MB se persistía y dejaba al guild sin
	// bienvenidas para siempre (Discord lo rechaza con 400 y el error sólo
	// aparece en los logs del bot).
	if verr := validations.ValidateUpdateModuleGreeter(&body); verr != nil {
		r.AddError(verr)
		return reply(c, r)
	}

	patch, err := patchMap(c.Body())
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	sourced, err := h.Repo.Update(ctx, c.Params("bot_id"), c.Params("guild_id"), patch)
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		// data:null parity — the Node greeter controller runs
		// applySourceAndStash(sourced{data:null}) before throwing
		// MODULE_NOT_FOUND on both the GET and the update-null PATCH branch.
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))
		return reply(c, r)
	}
	d := sourced.Data
	r.SetData(&d)
	r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	return reply(c, r)
}

