```
export function usePatchSubmitter<T extends object>(
	opts: PatchSubmitterOptions<T>,
): (value: T) => void {
	const { normalized, module, fetcher, skipKeys, extendDiff, dependencies, rev } =
		opts;

	// Refs capture the LIVE `normalized`/`module` at click time. The onSubmit
	// closure captured by TanStack Form would otherwise diff against stale
	// values after Redux updates and revalidations.
	const normalizedRef = useRef(normalized);
	const moduleRef = useRef(module);
	useEffect(() => {
		normalizedRef.current = normalized;
		moduleRef.current = module;
	}, [normalized, module]);

	// Misma razón que arriba: la revisión cambia en cada guardado + revalidación,
	// y meterla en las dependencias del `useCallback` rompería la estabilidad del
	// callback que TanStack Form captura.
	const revRef = useRef(rev);
	useEffect(() => {
		revRef.current = rev;
	}, [rev]);

	return useCallback(
		(value: T) => {
			if (document.activeElement instanceof HTMLElement) {
				document.activeElement.blur();
			}
			const current = normalizedRef.current;
			const diff = computeTopLevelDiff(value, current, skipKeys);
			extendDiff?.(diff, value, moduleRef.current);
			widenDiffForDependencies(dependencies ?? [], diff, value);
			if (Object.keys(diff).length === 0) return;
			// Solo `pnpm dev` (dev server = MODE "development"): imprime el objeto
			// exacto que se va a enviar al servidor. Silencioso en prod y en tests.
			if (import.meta.env.MODE === "development") {
				Logger.info("form:patch", diff);
			}
			// La revisión se añade aquí, ya pasada la comprobación de "no hay nada
			// que guardar", para que nunca cuente como un cambio.
			const currentRev = revRef.current;
			const payload =
				currentRev == null ? diff : { ...diff, [MODULE_REV_KEY]: currentRev };
			fetcher.submit(payload, {
				method: "post",
				encType: "application/json",
			});
		},
		[fetcher, skipKeys, extendDiff, dependencies],
	);
}
```

3. useSendChangeValidator · function  [symbol]
   web/dash.kena.bot/app/features/form/hooks/useModuleForm.ts:L161-L186
   function useSendChangeValidator<T extends object>( opts: SendChangeValidatorOptions<T>, ): (ctx: { value: T }) => undefined | { fields: Record<string, string> }

```
export function useSendChangeValidator<T extends object>(
	opts: SendChangeValidatorOptions<T>,
): (ctx: { value: T }) => undefined | { fields: Record<string, string> } {
	const { normalized, schema, skipKeys, dependencies } = opts;

	const normalizedRef = useRef(normalized);
	useEffect(() => {
		normalizedRef.current = normalized;
	}, [normalized]);

	return useCallback(
		({ value }: { value: T }) => {
			const diff = computeTopLevelDiff(value, normalizedRef.current, skipKeys);
			widenDiffForDependencies(dependencies ?? [], diff, value);
			if (Object.keys(diff).length === 0) return undefined;
			const result = schema.safeParse(diff);
			if (result.success) return undefined;
			const fields: Record<string, string> = {};
			for (const issue of result.error.issues) {
				fields[issue.path.join(".")] = issue.message;
			}
			return { fields };
		},
		[schema, skipKeys, dependencies],
	);
}
```

