package validations

import (
	"encoding/json"
	"math"
	"regexp"
	"strings"

	"kena.bot/api-db-go/internal/domain/dbinfraction"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
)

// Request DTOs + parsers for the `/moderation/infractions` router. Field shapes
// mirror the Zod schemas in
// `services/api-db/src/domain/zod-schemas/validations/moderation-infractions-validations.ts`.
// The moderation-infractions controller wraps every parse in `captureErrors`, so
// a validation failure is a STRUCTURED 400 (ZOD context) — exactly like the
// /music + /giveaways verticals. Every failure returns the exact Zod v4.3.6
// message via `zodItemError` (context "ZOD", property = `issue.path.join(".")`),
// surfacing the FIRST failing issue.
//
// CRITICAL datetime divergence from the giveaways / kpis verticals (plan A.22):
// the moderation datetime fields use `z.string().datetime({ offset: true })`,
// which ACCEPTS a non-UTC offset (`+02:00`), UNLIKE `z.string().datetime()` /
// `z.iso.datetime()` (which require a literal `Z`). The regex below therefore
// admits `Z` OR `±HH:MM`; a failure still degrades to the shared `Invalid ISO
// datetime` message (same as the strict-UTC verticals).
//
// Create takes the materialized dbinfraction.CreateData (the Node repo runs a
// FIXED-column INSERT with `?? default`); Update builds a `map[string]any` of
// present columns (a present null → a nil map value → SQL NULL; absent → skipped
// → left unchanged; an empty map → the repo's findById fallback), reusing the
// track-errors / giveaways map helpers.

// ─── enum sets + messages (zod v4 `Invalid option: expected one of ...`) ──

var infractionTypeSet = map[string]bool{
	dbinfraction.TypeWarn: true, dbinfraction.TypeNote: true, dbinfraction.TypeMute: true,
	dbinfraction.TypeTempmute: true, dbinfraction.TypeUnmute: true, dbinfraction.TypeKick: true,
	dbinfraction.TypeBan: true, dbinfraction.TypeTempban: true, dbinfraction.TypeUnban: true,
	dbinfraction.TypeBlind: true,
}

var infractionStatusSet = map[string]bool{
	dbinfraction.StatusActive: true, dbinfraction.StatusPending: true,
	dbinfraction.StatusExpired: true, dbinfraction.StatusRevoked: true,
}

// infractionSourceSet incluye `system` (migración 025): es el origen que estampan
// los automatismos del módulo (escalado, anti-raid, filtro de entrada, anti-nuke).
// Vale tanto para el POST de creación como para el filtro `?source=` del listado —
// ambos comparten este set.
var infractionSourceSet = map[string]bool{
	dbinfraction.SourceManual: true, dbinfraction.SourceAutomod: true,
	dbinfraction.SourceAPI: true, dbinfraction.SourceDiscord: true,
	dbinfraction.SourceSystem: true,
}

var infractionMechanismSet = map[string]bool{
	dbinfraction.MechanismTimeout: true, dbinfraction.MechanismRole: true,

