1	import type * as z from "zod";
2	import { deepEqual } from "@/lib/deepEqual";
3	
4	// Declarative "field X requires field Y" rule. Declared once per module and
5	// fed to BOTH the send-schema's superRefine (validation) and the diff widener
6	// (payload pairing) so the two never drift apart.
7	export interface FieldDependency {
8		/** dotted path that triggers the rule, e.g. "captcha.enabled" */
9		when: string;
10		/** predicate over the value of `when`; default: (v) => v === true */
11		is?: (v: unknown) => boolean;
12		/** dotted path of the required field, e.g. "captcha.verified_role_id" */
13		requires: string;
14		/** "is missing" predicate; default: (v) => v == null || v === "" */
15		missing?: (v: unknown) => boolean;
16		/** i18n key of the issue; if OMITTED, the rule only widens the payload
17		 *  (it never validates). */
18		message?: string;
19		/** Metadata for the generic banner and the tab jump. Without `ui`, the rule
20		 *  never appears in the banner (it only validates / widens the payload). */
21		ui?: {
22			/** value of the tab (`useUrlTab`) where the `requires` field renders */
23			tab: string;
24			/** i18n key of the banner text ("X is enabled but Y is missing") */
25			label: string;
26		};
