func TestGuildArrayQueryIDsSplitsAndTrims(t *testing.T) {
	q := GuildArrayQuery{GuildIDs: " 1 , 2,3,, 4 "}
	got := q.IDs()
	want := []string{"1", "2", "3", "4"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("IDs = %v, want %v", got, want)
	}
}

func TestGuildArrayQueryIDsEmptyInputProducesEmptySlice(t *testing.T) {
	q := GuildArrayQuery{GuildIDs: ""}
	if got := q.IDs(); len(got) != 0 {
		t.Fatalf("empty IDs slice expected, got %v", got)
	}
}

func TestGuildQueryIncludesModules(t *testing.T) {
	if !(GuildQuery{Modules: "true"}.IncludesModules()) {
		t.Fatal("modules=true should toggle inclusion on")
	}
	for _, v := range []string{"", "false", "yes", "1"} {
		if (GuildQuery{Modules: v}.IncludesModules()) {
			t.Fatalf("modules=%q should NOT toggle inclusion (paridad TS strict ==)", v)
		}
	}
}

func TestUpdateGuildBodyToSetOnlyIncludesPresentFields(t *testing.T) {
	prefix := "?"
	enabled := true
	b := UpdateGuildBody{
		Prefix:            &prefix,
		EnabledEmbedColor: &enabled,
	}
	set := b.ToSet()
	if got, ok := set["prefix"]; !ok || got != "?" {
		t.Fatalf("prefix missing or wrong: %v", set)
	}
	if got, ok := set["enabled_embed_color"]; !ok || got != true {
		t.Fatalf("enabled_embed_color missing or wrong: %v", set)
	}
	// Fields the caller did NOT set must NOT appear in the $set payload
	// — otherwise the PATCH endpoint becomes destructive on every call.
	for _, forbidden := range []string{"bot_id", "guild_id", "language", "embed_color", "permissions"} {
		if _, ok := set[forbidden]; ok {
			t.Fatalf("$set should not contain %s when body omitted it: %v", forbidden, set)
		}
	}
}

func TestUpdateGuildBodyToSetEmpty(t *testing.T) {
	if got := (UpdateGuildBody{}).ToSet(); got != nil {
		t.Fatalf("empty body must produce nil $set, got %v", got)
	}
}

