// ─── PATCH-map enum normalization + "impossible config" rejection ─────────
//
// `UpdateModuleModerationBody` above only checks JSON SHAPE — unknown keys
// (`DisallowUnknownFields`) and JSON type (`encoding/json`) — same as every
// other Go module body (see the doc comment above). It does NOT check that an
// enum STRING is one of the closed values the Node zod schema allows: nothing
// stopped a direct API call (skipping the dashboard's zod entirely) from
// persisting `"mute":{"mode":"portal"}`, or a config the bot literally cannot
// carry out.
//
// NormalizeModerationPatch closes that gap on the RAW patch map — the same
// map `patchMap` hands to `mongo.MergeDeepJSON` — instead of the typed struct
// above: only the map preserves per-leaf KEY PRESENCE, which is what lets an
// enum sent as `""` (what an unset dashboard `<select>` serializes as) be
// told apart from one the caller deliberately picked.
//
//   - An enum leaf sent as `""` is NORMALIZED: the key is dropped from the
//     patch so the merge leaves the stored value untouched — "no elegido
//     todavía", never "configured to nothing".
//   - An enum leaf sent as anything else outside its closed set is REJECTED
//     (400, zod-shaped): that value is impossible for the bot to act on, the
//     same class of error the browser's zod already caught.
//   - ONE cross-field impossibility is rejected too: `mute.mode === "role"`
//     with no `mute.role_id` in the SAME patch object (mirrors
//     `moderationDependencies` in `moderation-schema.ts` — a role-mute the bot
//     cannot apply). Every other v3 block deliberately has NO such rule: it
//     degrades on its own (see that same comment) — replicating one here
//     would be exactly the false guard that was removed from tempvoice.
//
// This does NOT replicate the rest of the zod schema (string max-lengths,
// numeric ranges, array sizes): those are Discord-side / cosmetic limits, not
// configs the bot is literally unable to execute — out of scope on purpose.
func NormalizeModerationPatch(patch map[string]any) *apierrors.CustomError {
	if verr := normalizeEnumLeaf(patch, "command_mode", moderationCommandModeSet, moderationCommandModeMsg, "command_mode"); verr != nil {
		return verr
	}
	if verr := normalizeModerationMute(patch); verr != nil {
		return verr
	}
	if verr := normalizeModerationAutomod(patch); verr != nil {
		return verr
	}
	if verr := normalizeModerationEscalation(patch); verr != nil {
		return verr
	}
	if verr := normalizeModerationEffects(patch); verr != nil {
		return verr
	}
	if verr := normalizeEnumObjectLeaf(patch, "raid", "action", moderationRaidActionSet, moderationRaidActionMsg, "raid.action"); verr != nil {
		return verr
	}
	if verr := normalizeEnumObjectLeaf(patch, "gate", "action", moderationGateActionSet, moderationGateActionMsg, "gate.action"); verr != nil {
		return verr
	}
	if verr := normalizeModerationAntinuke(patch); verr != nil {
		return verr
	}
	return nil
}

// asObject reads `patch[key]` as a nested JSON object. Absent key or a
// non-object value (e.g. a client sending `"mute": null`) both return
// `false` — nothing to normalize, and not this function's job to reject.
func asObject(patch map[string]any, key string) (map[string]any, bool) {
	v, ok := patch[key]
	if !ok {
		return nil, false
	}
	m, ok := v.(map[string]any)
	return m, ok
}

// normalizeEnumLeaf drops `obj[key]` when it is `""` (see doc above) and
// rejects it when it is a non-empty string outside `allowed`. A missing key
// or a non-string value (already caught upstream by the strict struct
// decode) is left untouched.
func normalizeEnumLeaf(obj map[string]any, key string, allowed map[string]bool, msg, property string) *apierrors.CustomError {
	v, ok := obj[key]
	if !ok {
		return nil
	}
	s, isStr := v.(string)
	if !isStr {
		return nil
	}
	if s == "" {
		delete(obj, key)
		return nil
	}
	if !allowed[s] {
		return zodItemError(msg, property)
	}
	return nil
}

// normalizeEnumObjectLeaf is normalizeEnumLeaf for a leaf nested one object
// down (`patch[objKey][leafKey]`), e.g. `raid.action` / `gate.action`.
func normalizeEnumObjectLeaf(patch map[string]any, objKey, leafKey string, allowed map[string]bool, msg, property string) *apierrors.CustomError {
	obj, ok := asObject(patch, objKey)
	if !ok {
		return nil
	}
	return normalizeEnumLeaf(obj, leafKey, allowed, msg, property)
}

const moderationMuteRoleRequiredMsg = `mute.role_id is required when mute.mode is "role"`

// normalizeModerationMute normalizes `mute.mode` and rejects the one
// cross-field impossibility this module guards: a role-mute with no role.
func normalizeModerationMute(patch map[string]any) *apierrors.CustomError {
	mute, ok := asObject(patch, "mute")
	if !ok {
		return nil
	}
	if verr := normalizeEnumLeaf(mute, "mode", moderationMuteModeSet, moderationMuteModeMsg, "mute.mode"); verr != nil {
		return verr
	}
	// `mode` was either absent to start with or normalized away above when
