11	// UpdateModuleModerationBody mirrors the Node `updateModuleModerationSchema`
12	// (a `.strict()` object of `.optional()` fields). The handler decodes this
13	// with `DisallowUnknownFields` (matching the zod `.strict()` — unknown
14	// keys top-level OR nested are a 400) and then re-decodes the SAME raw
15	// body as `map[string]any`, which the repository merges into the existing
16	// subdoc via `mongo.MergeDeepJSON` by KEY PRESENCE: a key absent in the
17	// body is left alone; an explicit `false`/`0`/`""`/`null` is applied and
18	// overrides the stored value; nested objects (`commands_global`, `mute`,
19	// `automod`) recurse; the `commands` map merges per-key; slices replace
20	// wholesale.
21	//
22	// UNLIKE the READ schema, the PATCH schema exposes NO `schema_version`
23	// / `updated_at` — those are stamped by the repo on every write. Every
24	// other READ field IS patchable here (the READ and PATCH catalogs
25	// otherwise match).
26	//
27	// `log_channel_id` is the only TOP-LEVEL nullable string (`string |
28	// null`). Because merge is presence-based, sending `null` clears it to
29	// null and omitting the key preserves the stored value — exactly like
30	// Node's `mergeDeep`, with no special-case handling in this struct. The
31	// nested nullables (`mute.role_id`, each command's `dm_embed.color`)
32	// ride inside their parent structs and are merged recursively.
33	//
34	// REMAINING CAVEATS (inherited from the old MergeDeep mold, NOT from
35	// presence-based behaviour):
36	//   - Go's json decoder does NOT enforce zod's REQUIRED-ness inside a
37	//     present nested object (Node's `commandAccessUpdateSchema` /
38	//     `automod*` rule schemas are `.strict()` with every field
39	//     required), so a partial nested object that Node would 400 is
40	//     accepted here and the missing leaves stay zero — the same
41	//     non-strict-required behaviour every Go module body has.
42	//   - The zod value constraints (`dm_embed.content` max 4000) are NOT
43	//     enforced here. Same as every other Go module body.
44	//
45	// Cada clave de nivel superior del schema DEBE tener su puntero aquí: si falta
46	// una, el PATCH de la dashboard se come un 400 "unknown field" (el handler
47	// decodifica con `DisallowUnknownFields`). Por eso los siete bloques del v3
48	// (`protection`, `escalation`, `effects`, `raid`, `gate`, `antinuke`,
49	// `lockdown`) están listados igual que `automod` — y `flows` (v4) igual.
50	//
51	// `Flows` reutiliza `dbguild.ModerationFlow` TAL CUAL (mismo precedente que
52	// `Creators *[]dbguild.TempvoiceCreator` / `TicketTypes *[]dbguild.TicketsType`
53	// / `TicketTypes *[]dbguild.ModmailTicketType`), no un tipo "Body" duplicado:
54	// el struct de dominio YA tiene exactamente la forma que la dashboard envía
55	// (§5.3 del contrato de flujos: el PATCH sustituye el array ENTERO, así que
56	// cada flujo llega completo, con `id`/`created_at`/`updated_at` incluidos).
57	// Los `params` de trigger/condiciones/pasos siguen siendo `map[string]any`
58	// libre — su forma la valida el catálogo compartido, no Go — así que
59	// `DisallowUnknownFields` no los toca; sí rechaza cualquier clave desconocida
60	// a nivel de `ModerationFlow`/`ModerationFlowScope`/etc., que es justo lo que
61	// se quiere.
62	type UpdateModuleModerationBody struct {
63		Enabled            *bool                                 `json:"enabled,omitempty"`
64		CommandMode        *dbguild.ModerationCommandMode        `json:"command_mode,omitempty"`
65		CommandsGlobal     *dbguild.ModerationCommandAccess      `json:"commands_global,omitempty"`
66		Commands           *map[string]dbguild.ModerationCommand `json:"commands,omitempty"`
67		Mute               *dbguild.ModerationMute               `json:"mute,omitempty"`
68		LogChannelID       *string                               `json:"log_channel_id,omitempty"`
69		TrackNativeActions *bool                                 `json:"track_native_actions,omitempty"`
70		Automod            *dbguild.ModerationAutomod            `json:"automod,omitempty"`
71		Protection         *dbguild.ModerationProtection         `json:"protection,omitempty"`
72		Escalation         *dbguild.ModerationEscalation         `json:"escalation,omitempty"`
73		Effects            *dbguild.ModerationEffects            `json:"effects,omitempty"`
74		Raid               *dbguild.ModerationRaid               `json:"raid,omitempty"`
75		Gate               *dbguild.ModerationGate               `json:"gate,omitempty"`
76		Antinuke           *dbguild.ModerationAntinuke           `json:"antinuke,omitempty"`
77		Lockdown           *dbguild.ModerationLockdown           `json:"lockdown,omitempty"`
78		Flows              *[]dbguild.ModerationFlow             `json:"flows,omitempty"`
79	}
80	
81	// ─── PATCH-map enum normalization + "impossible config" rejection ─────────
82	//
83	// `UpdateModuleModerationBody` above only checks JSON SHAPE — unknown keys
84	// (`DisallowUnknownFields`) and JSON type (`encoding/json`) — same as every
85	// other Go module body (see the doc comment above). It does NOT check that an
86	// enum STRING is one of the closed values the Node zod schema allows: nothing
87	// stopped a direct API call (skipping the dashboard's zod entirely) from
88	// persisting `"mute":{"mode":"portal"}`, or a config the bot literally cannot
89	// carry out.
90	//
91	// NormalizeModerationPatch closes that gap on the RAW patch map — the same
92	// map `patchMap` hands to `mongo.MergeDeepJSON` — instead of the typed struct
93	// above: only the map preserves per-leaf KEY PRESENCE, which is what lets an
94	// enum sent as `""` (what an unset dashboard `<select>` serializes as) be
95	// told apart from one the caller deliberately picked.
96	//
97	//   - An enum leaf sent as `""` is NORMALIZED: the key is dropped from the
98	//     patch so the merge leaves the stored value untouched — "no elegido
99	//     todavía", never "configured to nothing".
100	//   - An enum leaf sent as anything else outside its closed set is REJECTED
101	//     (400, zod-shaped): that value is impossible for the bot to act on, the
102	//     same class of error the browser's zod already caught.
103	//   - ONE cross-field impossibility is rejected too: `mute.mode === "role"`
104	//     with no `mute.role_id` in the SAME patch object (mirrors
105	//     `moderationDependencies` in `moderation-schema.ts` — a role-mute the bot
106	//     cannot apply). Every other v3 block deliberately has NO such rule: it
107	//     degrades on its own (see that same comment) — replicating one here
108	//     would be exactly the false guard that was removed from tempvoice.
109	//
110	// This does NOT replicate the rest of the zod schema (string max-lengths,
111	// numeric ranges, array sizes): those are Discord-side / cosmetic limits, not
112	// configs the bot is literally unable to execute — out of scope on purpose.
113	func NormalizeModerationPatch(patch map[string]any) *apierrors.CustomError {
114		if verr := normalizeEnumLeaf(patch, "command_mode", moderationCommandModeSet, moderationCommandModeMsg, "command_mode"); verr != nil {
115			return verr
116		}
117		if verr := normalizeModerationMute(patch); verr != nil {
118			return verr
119		}
120		if verr := normalizeModerationAutomod(patch); verr != nil {
121			return verr
122		}
123		if verr := normalizeModerationEscalation(patch); verr != nil {
124			return verr
125		}
126		if verr := normalizeModerationEffects(patch); verr != nil {
127			return verr
128		}
129		if verr := normalizeEnumObjectLeaf(patch, "raid", "action", moderationRaidActionSet, moderationRaidActionMsg, "raid.action"); verr != nil {
130			return verr
131		}
132		if verr := normalizeEnumObjectLeaf(patch, "gate", "action", moderationGateActionSet, moderationGateActionMsg, "gate.action"); verr != nil {
133			return verr
134		}
135		if verr := normalizeModerationAntinuke(patch); verr != nil {
136			return verr
137		}
138		return nil
139	}
140	
141	// asObject reads `patch[key]` as a nested JSON object. Absent key or a
142	// non-object value (e.g. a client sending `"mute": null`) both return
143	// `false` — nothing to normalize, and not this function's job to reject.
144	func asObject(patch map[string]any, key string) (map[string]any, bool) {
145		v, ok := patch[key]
146		if !ok {
147			return nil, false
148		}
149		m, ok := v.(map[string]any)
150		return m, ok
151	}
152	
153	// normalizeEnumLeaf drops `obj[key]` when it is `""` (see doc above) and
154	// rejects it when it is a non-empty string outside `allowed`. A missing key
155	// or a non-string value (already caught upstream by the strict struct
156	// decode) is left untouched.
157	func normalizeEnumLeaf(obj map[string]any, key string, allowed map[string]bool, msg, property string) *apierrors.CustomError {
158		v, ok := obj[key]
159		if !ok {
160			return nil
161		}
162		s, isStr := v.(string)
163		if !isStr {
164			return nil
165		}
166		if s == "" {
167			delete(obj, key)
168			return nil
169		}
170		if !allowed[s] {
171			return zodItemError(msg, property)
172		}
173		return nil
174	}
175	
176	// normalizeEnumObjectLeaf is normalizeEnumLeaf for a leaf nested one object
177	// down (`patch[objKey][leafKey]`), e.g. `raid.action` / `gate.action`.
178	func normalizeEnumObjectLeaf(patch map[string]any, objKey, leafKey string, allowed map[string]bool, msg, property string) *apierrors.CustomError {
179		obj, ok := asObject(patch, objKey)
180		if !ok {
181			return nil
182		}
183		return normalizeEnumLeaf(obj, leafKey, allowed, msg, property)
184	}
185	
186	const moderationMuteRoleRequiredMsg = `mute.role_id is required when mute.mode is "role"`
187	
188	// normalizeModerationMute normalizes `mute.mode` and rejects the one
189	// cross-field impossibility this module guards: a role-mute with no role.
190	func normalizeModerationMute(patch map[string]any) *apierrors.CustomError {
191		mute, ok := asObject(patch, "mute")
192		if !ok {
193			return nil
194		}
195		if verr := normalizeEnumLeaf(mute, "mode", moderationMuteModeSet, moderationMuteModeMsg, "mute.mode"); verr != nil {
196			return verr
197		}
198		// `mode` was either absent to start with or normalized away above when
199		// empty — either way, this PATCH isn't the one switching to "role", so the
200		// dependency isn't this call's to enforce.
201		mode, sentMode := mute["mode"].(string)
202		if !sentMode || mode != string(dbguild.ModerationMuteModeRole) {
203			return nil
204		}
205		roleID, hasRoleID := mute["role_id"]
206		if !hasRoleID || roleID == nil {
207			return zodItemError(moderationMuteRoleRequiredMsg, "mute.role_id")
208		}
209		if s, isStr := roleID.(string); isStr && s == "" {
210			return zodItemError(moderationMuteRoleRequiredMsg, "mute.role_id")
211		}
212		return nil
213	}
214	
215	// moderationAutomodRuleKeys are the nine AutoMod rule blocks, each carrying
216	// its own `action` enum.
217	var moderationAutomodRuleKeys = []string{
218		"mentions", "words", "invites", "spam", "duplicates", "caps", "links", "emojis", "attachments",
219	}
220	
221	func normalizeModerationAutomod(patch map[string]any) *apierrors.CustomError {
222		automod, ok := asObject(patch, "automod")
223		if !ok {
224			return nil
225		}
226		for _, rule := range moderationAutomodRuleKeys {
227			ruleObj, ok := automod[rule].(map[string]any)
228			if !ok {
229				continue
230			}
231			property := "automod." + rule + ".action"
232			if verr := normalizeEnumLeaf(ruleObj, "action", automodActionSet, automodActionMsg, property); verr != nil {
233				return verr
234			}
235		}
236		return nil
237	}
238	
239	func normalizeModerationEscalation(patch map[string]any) *apierrors.CustomError {
240		escalation, ok := asObject(patch, "escalation")
241		if !ok {
242			return nil
243		}
244		rules, ok := escalation["rules"].([]any)
245		if !ok {
246			return nil
247		}
248		for i, item := range rules {
249			rule, ok := item.(map[string]any)
250			if !ok {
251				continue
252			}
253			property := fmt.Sprintf("escalation.rules.%d.action", i)
254			if verr := normalizeEnumLeaf(rule, "action", moderationEscalationActionSet, moderationEscalationActionMsg, property); verr != nil {
255				return verr
256			}
257		}
258		return nil
259	}
260	
261	// moderationEffectKeys are the five sanction-effect blocks, each carrying its
262	// own `policy` enum.
263	var moderationEffectKeys = []string{
264		"voice_disconnect_on_mute", "server_mute_on_mute", "strip_roles_on_mute",
265		"purge_on_ban", "purge_on_kick",
266	}
267	
268	func normalizeModerationEffects(patch map[string]any) *apierrors.CustomError {
269		effects, ok := asObject(patch, "effects")
270		if !ok {
271			return nil
272		}
273		for _, key := range moderationEffectKeys {
274			effect, ok := effects[key].(map[string]any)
275			if !ok {
276				continue
277			}
278			property := "effects." + key + ".policy"
279			if verr := normalizeEnumLeaf(effect, "policy", moderationEffectPolicySet, moderationEffectPolicyMsg, property); verr != nil {
280				return verr
281			}
282		}
283		return nil
284	}
285	
286	// normalizeModerationAntinuke normalizes the block-level `punishment`
287	// (closed set, no `inherit`) and each per-action `limits[...].punishment`
288	// (same set PLUS `inherit`).
289	func normalizeModerationAntinuke(patch map[string]any) *apierrors.CustomError {
290		antinuke, ok := asObject(patch, "antinuke")
291		if !ok {
292			return nil
293		}
294		if verr := normalizeEnumLeaf(antinuke, "punishment", moderationNukePunishmentSet, moderationNukePunishmentMsg, "antinuke.punishment"); verr != nil {
295			return verr
296		}
297		limits, ok := antinuke["limits"].(map[string]any)
298		if !ok {
299			return nil
300		}
301		for action, item := range limits {
302			limit, ok := item.(map[string]any)
303			if !ok {
304				continue
305			}
306			property := "antinuke.limits." + action + ".punishment"
307			if verr := normalizeEnumLeaf(limit, "punishment", moderationNukePunishmentInheritSet, moderationNukePunishmentInheritMsg, property); verr != nil {
308				return verr
309			}
310		}
311		return nil
312	}
313	
314	// ─── enum sets + messages (zod v4 `Invalid option: expected one of ...`) ──
315	
316	var moderationCommandModeSet = map[string]bool{"slash": true, "prefix": true, "both": true}
317	
318	const moderationCommandModeMsg = `Invalid option: expected one of "slash"|"prefix"|"both"`
319	
320	var moderationMuteModeSet = map[string]bool{"auto": true, "timeout": true, "role": true}
321	
322	const moderationMuteModeMsg = `Invalid option: expected one of "auto"|"timeout"|"role"`
323	
324	var automodActionSet = map[string]bool{
325		"delete": true, "delete_warn": true, "delete_timeout": true, "delete_kick": true, "delete_ban": true,
326	}
327	
328	const automodActionMsg = `Invalid option: expected one of "delete"|"delete_warn"|"delete_timeout"|"delete_kick"|"delete_ban"`
329	
330	var moderationEscalationActionSet = map[string]bool{
331		"mute": true, "tempmute": true, "kick": true, "tempban": true, "ban": true,
332	}
333	
334	const moderationEscalationActionMsg = `Invalid option: expected one of "mute"|"tempmute"|"kick"|"tempban"|"ban"`
335	
336	var moderationEffectPolicySet = map[string]bool{"always": true, "never": true, "ask": true}
337	
338	const moderationEffectPolicyMsg = `Invalid option: expected one of "always"|"never"|"ask"`
339	
340	var moderationRaidActionSet = map[string]bool{"alert": true, "lockdown": true, "kick": true, "ban": true}
341	
342	const moderationRaidActionMsg = `Invalid option: expected one of "alert"|"lockdown"|"kick"|"ban"`
343	
344	var moderationGateActionSet = map[string]bool{"alert": true, "kick": true, "ban": true, "mute": true}
345	
346	const moderationGateActionMsg = `Invalid option: expected one of "alert"|"kick"|"ban"|"mute"`
347	
348	var moderationNukePunishmentSet = map[string]bool{
349		"alert": true, "strip_roles": true, "kick": true, "ban": true,
350	}
351	
352	const moderationNukePunishmentMsg = `Invalid option: expected one of "alert"|"strip_roles"|"kick"|"ban"`
353	
354	var moderationNukePunishmentInheritSet = map[string]bool{
355		"alert": true, "strip_roles": true, "kick": true, "ban": true, "inherit": true,
356	}
357	
358	const moderationNukePunishmentInheritMsg = `Invalid option: expected one of "alert"|"strip_roles"|"kick"|"ban"|"inherit"`
359

