		t.Fatalf("an unset mute.mode should normalize, not reject, got error: %v", verr)
	}
	mute, _ := patch["mute"].(map[string]any)
	if _, ok := mute["mode"]; ok {
		t.Fatalf("empty mute.mode should be dropped, got %v", mute)
	}
}

func TestNormalizeModerationPatchMuteOtherModesDoNotRequireRoleID(t *testing.T) {
	for _, mode := range []string{"auto", "timeout"} {
		patch := map[string]any{"mute": map[string]any{"mode": mode}}
		if verr := NormalizeModerationPatch(patch); verr != nil {
			t.Fatalf("mute.mode=%s should not require role_id, got error: %v", mode, verr)
		}
	}
}

func TestNormalizeModerationPatchAutomodInvalidActionIsRejectedWithItsPath(t *testing.T) {
	patch := map[string]any{
		"automod": map[string]any{
			"words": map[string]any{"action": "explode"},
		},
	}
	verr := NormalizeModerationPatch(patch)
	if verr == nil {
		t.Fatal("invalid automod rule action should be rejected")
	}
	if got := verr.Metadata["property"]; got != "automod.words.action" {
		t.Fatalf("property = %v, want automod.words.action", got)
	}
}

func TestNormalizeModerationPatchAutomodEmptyActionIsNormalized(t *testing.T) {
	patch := map[string]any{
		"automod": map[string]any{
			"caps": map[string]any{"action": "", "min_length": float64(10)},
		},
	}
	if verr := NormalizeModerationPatch(patch); verr != nil {
		t.Fatalf("empty automod rule action should normalize, got error: %v", verr)
	}
	caps, _ := patch["automod"].(map[string]any)["caps"].(map[string]any)
	if _, ok := caps["action"]; ok {
		t.Fatalf("empty automod action should be dropped, got %v", caps)
	}
	if caps["min_length"] != float64(10) {
		t.Fatalf("sibling fields must survive normalization, got %v", caps)
	}
}

func TestNormalizeModerationPatchEscalationRuleInvalidActionReportsIndex(t *testing.T) {
	patch := map[string]any{
		"escalation": map[string]any{
			"rules": []any{
				map[string]any{"threshold": float64(3), "action": "mute"},
				map[string]any{"threshold": float64(5), "action": "explode"},
			},
		},
	}
	verr := NormalizeModerationPatch(patch)
	if verr == nil {
		t.Fatal("invalid escalation rule action should be rejected")
	}
	if got := verr.Metadata["property"]; got != "escalation.rules.1.action" {
		t.Fatalf("property = %v, want escalation.rules.1.action", got)
	}
}

func TestNormalizeModerationPatchEffectsInvalidPolicyIsRejected(t *testing.T) {
	patch := map[string]any{
		"effects": map[string]any{
			"purge_on_ban": map[string]any{"policy": "sometimes"},
		},
	}
	if verr := NormalizeModerationPatch(patch); verr == nil {
		t.Fatal("invalid effect policy should be rejected")
	}
}

func TestNormalizeModerationPatchRaidAndGateInvalidActionAreRejected(t *testing.T) {
	if verr := NormalizeModerationPatch(map[string]any{
		"raid": map[string]any{"action": "explode"},
	}); verr == nil {
		t.Fatal("invalid raid.action should be rejected")
	}
	if verr := NormalizeModerationPatch(map[string]any{
		"gate": map[string]any{"action": "explode"},
	}); verr == nil {
		t.Fatal("invalid gate.action should be rejected")
	}
}

func TestNormalizeModerationPatchAntinukeTopLevelPunishmentRejectsInherit(t *testing.T) {
	// `inherit` only makes sense on a PER-LIMIT punishment (it means "use the
	// block-level punishment"), so the block-level punishment itself must not
	// accept it — there is nothing left to inherit from.
	patch := map[string]any{
		"antinuke": map[string]any{"punishment": "inherit"},
	}
	if verr := NormalizeModerationPatch(patch); verr == nil {
		t.Fatal("antinuke.punishment should reject \"inherit\"")
	}
}

func TestNormalizeModerationPatchAntinukeLimitPunishmentAllowsInherit(t *testing.T) {
	patch := map[string]any{
		"antinuke": map[string]any{
			"limits": map[string]any{
				"channel_delete": map[string]any{"punishment": "inherit"},
			},
		},
	}
	if verr := NormalizeModerationPatch(patch); verr != nil {
		t.Fatalf("a per-limit punishment of \"inherit\" should be valid, got error: %v", verr)
	}
}

func TestNormalizeModerationPatchAntinukeLimitInvalidPunishmentReportsAction(t *testing.T) {
	patch := map[string]any{
		"antinuke": map[string]any{
			"limits": map[string]any{
				"channel_delete": map[string]any{"punishment": "explode"},
			},
		},
	}
	verr := NormalizeModerationPatch(patch)
	if verr == nil {
		t.Fatal("invalid limit punishment should be rejected")
	}
	if got := verr.Metadata["property"]; got != "antinuke.limits.channel_delete.punishment" {
		t.Fatalf("property = %v, want antinuke.limits.channel_delete.punishment", got)
	}
}

func TestNormalizeModerationPatchAbsentKeysAreNoop(t *testing.T) {
	patch := map[string]any{"enabled": true, "log_channel_id": nil}
	if verr := NormalizeModerationPatch(patch); verr != nil {
		t.Fatalf("a patch with no enum leaves should pass through untouched, got error: %v", verr)
	}
	if len(patch) != 2 {
		t.Fatalf("patch should be untouched, got %v", patch)
	}
}

