package validations

import (
	"fmt"

	apierrors "kena.bot/api-db-go/internal/domain/errors"

	"kena.bot/api-db-go/internal/domain/dbguild"
)

// UpdateModuleModerationBody mirrors the Node `updateModuleModerationSchema`
// (a `.strict()` object of `.optional()` fields). The handler decodes this
// with `DisallowUnknownFields` (matching the zod `.strict()` — unknown
// keys top-level OR nested are a 400) and then re-decodes the SAME raw
// body as `map[string]any`, which the repository merges into the existing
// subdoc via `mongo.MergeDeepJSON` by KEY PRESENCE: a key absent in the
// body is left alone; an explicit `false`/`0`/`""`/`null` is applied and
// overrides the stored value; nested objects (`commands_global`, `mute`,
// `automod`) recurse; the `commands` map merges per-key; slices replace
// wholesale.
//
// UNLIKE the READ schema, the PATCH schema exposes NO `schema_version`
// / `updated_at` — those are stamped by the repo on every write. Every
// other READ field IS patchable here (the READ and PATCH catalogs
// otherwise match).
//
// `log_channel_id` is the only TOP-LEVEL nullable string (`string |
// null`). Because merge is presence-based, sending `null` clears it to
// null and omitting the key preserves the stored value — exactly like
// Node's `mergeDeep`, with no special-case handling in this struct. The
// nested nullables (`mute.role_id`, each command's `dm_embed.color`)
// ride inside their parent structs and are merged recursively.
//
// REMAINING CAVEATS (inherited from the old MergeDeep mold, NOT from
// presence-based behaviour):
//   - Go's json decoder does NOT enforce zod's REQUIRED-ness inside a
//     present nested object (Node's `commandAccessUpdateSchema` /
//     `automod*` rule schemas are `.strict()` with every field
//     required), so a partial nested object that Node would 400 is
//     accepted here and the missing leaves stay zero — the same
//     non-strict-required behaviour every Go module body has.
//   - The zod value constraints (`dm_embed.content` max 4000) are NOT
//     enforced here. Same as every other Go module body.
//
// Cada clave de nivel superior del schema DEBE tener su puntero aquí: si falta
// una, el PATCH de la dashboard se come un 400 "unknown field" (el handler
// decodifica con `DisallowUnknownFields`). Por eso los siete bloques del v3
// (`protection`, `escalation`, `effects`, `raid`, `gate`, `antinuke`,
// `lockdown`) están listados igual que `automod` — y `flows` (v4) igual.
//
// `Flows` reutiliza `dbguild.ModerationFlow` TAL CUAL (mismo precedente que
// `Creators *[]dbguild.TempvoiceCreator` / `TicketTypes *[]dbguild.TicketsType`
// / `TicketTypes *[]dbguild.ModmailTicketType`), no un tipo "Body" duplicado:
// el struct de dominio YA tiene exactamente la forma que la dashboard envía
// (§5.3 del contrato de flujos: el PATCH sustituye el array ENTERO, así que
// cada flujo llega completo, con `id`/`created_at`/`updated_at` incluidos).
// Los `params` de trigger/condiciones/pasos siguen siendo `map[string]any`
// libre — su forma la valida el catálogo compartido, no Go — así que
// `DisallowUnknownFields` no los toca; sí rechaza cualquier clave desconocida
// a nivel de `ModerationFlow`/`ModerationFlowScope`/etc., que es justo lo que
// se quiere.
type UpdateModuleModerationBody struct {
	Enabled            *bool                                 `json:"enabled,omitempty"`
	CommandMode        *dbguild.ModerationCommandMode        `json:"command_mode,omitempty"`
	CommandsGlobal     *dbguild.ModerationCommandAccess      `json:"commands_global,omitempty"`
	Commands           *map[string]dbguild.ModerationCommand `json:"commands,omitempty"`
	Mute               *dbguild.ModerationMute               `json:"mute,omitempty"`
	LogChannelID       *string                               `json:"log_channel_id,omitempty"`
	TrackNativeActions *bool                                 `json:"track_native_actions,omitempty"`
	Automod            *dbguild.ModerationAutomod            `json:"automod,omitempty"`
	Protection         *dbguild.ModerationProtection         `json:"protection,omitempty"`
	Escalation         *dbguild.ModerationEscalation         `json:"escalation,omitempty"`
	Effects            *dbguild.ModerationEffects            `json:"effects,omitempty"`
	Raid               *dbguild.ModerationRaid               `json:"raid,omitempty"`
	Gate               *dbguild.ModerationGate               `json:"gate,omitempty"`
	Antinuke           *dbguild.ModerationAntinuke           `json:"antinuke,omitempty"`
	Lockdown           *dbguild.ModerationLockdown           `json:"lockdown,omitempty"`
	Flows              *[]dbguild.ModerationFlow             `json:"flows,omitempty"`
}

// ─── PATCH-map enum normalization + "impossible config" rejection ─────────
//
// `UpdateModuleModerationBody` above only checks JSON SHAPE — unknown keys
// (`DisallowUnknownFields`) and JSON type (`encoding/json`) — same as every
// other Go module body (see the doc comment above). It does NOT check that an
// enum STRING is one of the closed values the Node zod schema allows: nothing
// stopped a direct API call (skipping the dashboard's zod entirely) from
// persisting `"mute":{"mode":"portal"}`, or a config the bot literally cannot
// carry out.
//
// NormalizeModerationPatch closes that gap on the RAW patch map — the same
// map `patchMap` hands to `mongo.MergeDeepJSON` — instead of the typed struct
// above: only the map preserves per-leaf KEY PRESENCE, which is what lets an
// enum sent as `""` (what an unset dashboard `<select>` serializes as) be
// told apart from one the caller deliberately picked.
//
//   - An enum leaf sent as `""` is NORMALIZED: the key is dropped from the
//     patch so the merge leaves the stored value untouched — "no elegido
//     todavía", never "configured to nothing".
//   - An enum leaf sent as anything else outside its closed set is REJECTED
//     (400, zod-shaped): that value is impossible for the bot to act on, the
//     same class of error the browser's zod already caught.
//   - ONE cross-field impossibility is rejected too: `mute.mode === "role"`
//     with no `mute.role_id` in the SAME patch object (mirrors
//     `moderationDependencies` in `moderation-schema.ts` — a role-mute the bot
//     cannot apply). Every other v3 block deliberately has NO such rule: it
//     degrades on its own (see that same comment) — replicating one here
//     would be exactly the false guard that was removed from tempvoice.
//
// This does NOT replicate the rest of the zod schema (string max-lengths,
// numeric ranges, array sizes): those are Discord-side / cosmetic limits, not
// configs the bot is literally unable to execute — out of scope on purpose.
func NormalizeModerationPatch(patch map[string]any) *apierrors.CustomError {
	if verr := normalizeEnumLeaf(patch, "command_mode", moderationCommandModeSet, moderationCommandModeMsg, "command_mode"); verr != nil {
		return verr
	}
	if verr := normalizeModerationMute(patch); verr != nil {
		return verr
	}
	if verr := normalizeModerationCommandsGlobal(patch); verr != nil {
		return verr
	}
	if verr := normalizeModerationCommands(patch); verr != nil {
		return verr
	}
	if verr := normalizeModerationAutomod(patch); verr != nil {
		return verr
	}
	if verr := normalizeModerationEscalation(patch); verr != nil {
		return verr
	}
	if verr := normalizeModerationEffects(patch); verr != nil {
		return verr
	}
	if verr := normalizeEnumObjectLeaf(patch, "raid", "action", moderationRaidActionSet, moderationRaidActionMsg, "raid.action"); verr != nil {
		return verr
	}
	if verr := normalizeEnumObjectLeaf(patch, "gate", "action", moderationGateActionSet, moderationGateActionMsg, "gate.action"); verr != nil {
		return verr
	}
	if verr := normalizeModerationAntinuke(patch); verr != nil {
		return verr
	}
	return nil
}

// asObject reads `patch[key]` as a nested JSON object. Absent key or a
// non-object value (e.g. a client sending `"mute": null`) both return
// `false` — nothing to normalize, and not this function's job to reject.
func asObject(patch map[string]any, key string) (map[string]any, bool) {
	v, ok := patch[key]
	if !ok {
		return nil, false
	}
	m, ok := v.(map[string]any)
	return m, ok
}

// normalizeEnumLeaf drops `obj[key]` when it is `""` (see doc above) and
// rejects it when it is a non-empty string outside `allowed`. A missing key
// or a non-string value (already caught upstream by the strict struct
// decode) is left untouched.
func normalizeEnumLeaf(obj map[string]any, key string, allowed map[string]bool, msg, property string) *apierrors.CustomError {
	v, ok := obj[key]
	if !ok {
		return nil
	}
	s, isStr := v.(string)
	if !isStr {
		return nil
	}
	if s == "" {
		delete(obj, key)
		return nil
	}
	if !allowed[s] {
		return zodItemError(msg, property)
	}
	return nil
}

// normalizeEnumObjectLeaf is normalizeEnumLeaf for a leaf nested one object
// down (`patch[objKey][leafKey]`), e.g. `raid.action` / `gate.action`.
func normalizeEnumObjectLeaf(patch map[string]any, objKey, leafKey string, allowed map[string]bool, msg, property string) *apierrors.CustomError {
	obj, ok := asObject(patch, objKey)
	if !ok {
		return nil
	}
	return normalizeEnumLeaf(obj, leafKey, allowed, msg, property)
}

const moderationMuteRoleRequiredMsg = `mute.role_id is required when mute.mode is "role"`

// normalizeModerationMute normalizes `mute.mode` and rejects the one
// cross-field impossibility this module guards: a role-mute with no role.
func normalizeModerationMute(patch map[string]any) *apierrors.CustomError {
	mute, ok := asObject(patch, "mute")
	if !ok {
		return nil
	}
	if verr := normalizeEnumLeaf(mute, "mode", moderationMuteModeSet, moderationMuteModeMsg, "mute.mode"); verr != nil {
		return verr
	}
	// `mode` was either absent to start with or normalized away above when
	// empty — either way, this PATCH isn't the one switching to "role", so the
	// dependency isn't this call's to enforce.
	mode, sentMode := mute["mode"].(string)
	if !sentMode || mode != string(dbguild.ModerationMuteModeRole) {
		return nil
	}
	roleID, hasRoleID := mute["role_id"]
	if !hasRoleID || roleID == nil {
		return zodItemError(moderationMuteRoleRequiredMsg, "mute.role_id")
	}
	if s, isStr := roleID.(string); isStr && s == "" {
		return zodItemError(moderationMuteRoleRequiredMsg, "mute.role_id")
	}
	return nil
}

// moderationAutomodRuleKeys are the nine AutoMod rule blocks, each carrying
// its own `action` enum.
var moderationAutomodRuleKeys = []string{
	"mentions", "words", "invites", "spam", "duplicates", "caps", "links", "emojis", "attachments",
}

func normalizeModerationAutomod(patch map[string]any) *apierrors.CustomError {
	automod, ok := asObject(patch, "automod")
	if !ok {
		return nil
	}
	for _, rule := range moderationAutomodRuleKeys {
		ruleObj, ok := automod[rule].(map[string]any)
		if !ok {
			continue
		}
		property := "automod." + rule + ".action"
		if verr := normalizeEnumLeaf(ruleObj, "action", automodActionSet, automodActionMsg, property); verr != nil {
			return verr
		}
	}
	return nil
}

func normalizeModerationEscalation(patch map[string]any) *apierrors.CustomError {
	escalation, ok := asObject(patch, "escalation")
	if !ok {
		return nil
	}
	rules, ok := escalation["rules"].([]any)
	if !ok {
		return nil
	}
	for i, item := range rules {
		rule, ok := item.(map[string]any)
		if !ok {
			continue
		}
		property := fmt.Sprintf("escalation.rules.%d.action", i)
		if verr := normalizeEnumLeaf(rule, "action", moderationEscalationActionSet, moderationEscalationActionMsg, property); verr != nil {
			return verr
		}
	}
	return nil
}

// moderationEffectKeys are the five sanction-effect blocks, each carrying its
// own `policy` enum.
var moderationEffectKeys = []string{
	"voice_disconnect_on_mute", "server_mute_on_mute", "strip_roles_on_mute",
	"purge_on_ban", "purge_on_kick",
}

func normalizeModerationEffects(patch map[string]any) *apierrors.CustomError {
	effects, ok := asObject(patch, "effects")
	if !ok {
		return nil
