var moderationEscalationActionSet = map[string]bool{
	"mute": true, "tempmute": true, "kick": true, "tempban": true, "ban": true,
}

const moderationEscalationActionMsg = `Invalid option: expected one of "mute"|"tempmute"|"kick"|"tempban"|"ban"`

var moderationEffectPolicySet = map[string]bool{"always": true, "never": true, "ask": true}

const moderationEffectPolicyMsg = `Invalid option: expected one of "always"|"never"|"ask"`

var moderationRaidActionSet = map[string]bool{"alert": true, "lockdown": true, "kick": true, "ban": true}

const moderationRaidActionMsg = `Invalid option: expected one of "alert"|"lockdown"|"kick"|"ban"`

var moderationGateActionSet = map[string]bool{"alert": true, "kick": true, "ban": true, "mute": true}

const moderationGateActionMsg = `Invalid option: expected one of "alert"|"kick"|"ban"|"mute"`

var moderationNukePunishmentSet = map[string]bool{
	"alert": true, "strip_roles": true, "kick": true, "ban": true,
}

const moderationNukePunishmentMsg = `Invalid option: expected one of "alert"|"strip_roles"|"kick"|"ban"`

var moderationNukePunishmentInheritSet = map[string]bool{
