package validations

import "testing"

func TestNormalizeModerationPatchEmptyCommandModeIsDroppedNotRejected(t *testing.T) {
	patch := map[string]any{"command_mode": ""}
	if verr := NormalizeModerationPatch(patch); verr != nil {
		t.Fatalf("empty command_mode should normalize, got error: %v", verr)
	}
	if _, ok := patch["command_mode"]; ok {
		t.Fatalf("empty command_mode should be dropped from the patch, got %v", patch)
	}
}

func TestNormalizeModerationPatchInvalidCommandModeIsRejected(t *testing.T) {
	patch := map[string]any{"command_mode": "portal"}
	verr := NormalizeModerationPatch(patch)
	if verr == nil {
		t.Fatal("invalid command_mode should be rejected")
	}
}

func TestNormalizeModerationPatchValidCommandModeSurvives(t *testing.T) {
	patch := map[string]any{"command_mode": "slash"}
	if verr := NormalizeModerationPatch(patch); verr != nil {
		t.Fatalf("valid command_mode should pass, got error: %v", verr)
	}
	if patch["command_mode"] != "slash" {
		t.Fatalf("valid command_mode should survive untouched, got %v", patch["command_mode"])
	}
}

func TestNormalizeModerationPatchMuteRoleModeWithoutRoleIDIsRejected(t *testing.T) {
	patch := map[string]any{
		"mute": map[string]any{"mode": "role", "role_id": nil},
	}
	verr := NormalizeModerationPatch(patch)
	if verr == nil {
		t.Fatal("mute.mode=role without mute.role_id should be rejected — the bot cannot apply it")
	}
}

func TestNormalizeModerationPatchMuteRoleModeWithEmptyRoleIDIsRejected(t *testing.T) {
	patch := map[string]any{
		"mute": map[string]any{"mode": "role", "role_id": ""},
	}
	if verr := NormalizeModerationPatch(patch); verr == nil {
		t.Fatal("mute.mode=role with an empty role_id should be rejected")
	}
}

func TestNormalizeModerationPatchMuteRoleModeWithRoleIDPasses(t *testing.T) {
	patch := map[string]any{
		"mute": map[string]any{"mode": "role", "role_id": "123"},
	}
	if verr := NormalizeModerationPatch(patch); verr != nil {
		t.Fatalf("mute.mode=role with a role_id should pass, got error: %v", verr)
	}
}

