11	// UpdateModuleModerationBody mirrors the Node `updateModuleModerationSchema`
12	// (a `.strict()` object of `.optional()` fields). The handler decodes this
13	// with `DisallowUnknownFields` (matching the zod `.strict()` — unknown
14	// keys top-level OR nested are a 400) and then re-decodes the SAME raw
15	// body as `map[string]any`, which the repository merges into the existing
16	// subdoc via `mongo.MergeDeepJSON` by KEY PRESENCE: a key absent in the
17	// body is left alone; an explicit `false`/`0`/`""`/`null` is applied and
18	// overrides the stored value; nested objects (`commands_global`, `mute`,
19	// `automod`) recurse; the `commands` map merges per-key; slices replace
20	// wholesale.
21	//
22	// UNLIKE the READ schema, the PATCH schema exposes NO `schema_version`
23	// / `updated_at` — those are stamped by the repo on every write. Every
24	// other READ field IS patchable here (the READ and PATCH catalogs
25	// otherwise match).
26	//
27	// `log_channel_id` is the only TOP-LEVEL nullable string (`string |
28	// null`). Because merge is presence-based, sending `null` clears it to
29	// null and omitting the key preserves the stored value — exactly like
30	// Node's `mergeDeep`, with no special-case handling in this struct. The
31	// nested nullables (`mute.role_id`, each command's `dm_embed.color`)
32	// ride inside their parent structs and are merged recursively.
33	//
34	// REMAINING CAVEATS (inherited from the old MergeDeep mold, NOT from
35	// presence-based behaviour):
36	//   - Go's json decoder does NOT enforce zod's REQUIRED-ness inside a
37	//     present nested object (Node's `commandAccessUpdateSchema` /
38	//     `automod*` rule schemas are `.strict()` with every field
39	//     required), so a partial nested object that Node would 400 is
40	//     accepted here and the missing leaves stay zero — the same
41	//     non-strict-required behaviour every Go module body has.
42	//   - The zod value constraints (`dm_embed.content` max 4000) are NOT
43	//     enforced here. Same as every other Go module body.
44	//
45	// Cada clave de nivel superior del schema DEBE tener su puntero aquí: si falta
46	// una, el PATCH de la dashboard se come un 400 "unknown field" (el handler
47	// decodifica con `DisallowUnknownFields`). Por eso los siete bloques del v3
48	// (`protection`, `escalation`, `effects`, `raid`, `gate`, `antinuke`,
49	// `lockdown`) están listados igual que `automod` — y `flows` (v4) igual.
50	//
51	// `Flows` reutiliza `dbguild.ModerationFlow` TAL CUAL (mismo precedente que
52	// `Creators *[]dbguild.TempvoiceCreator` / `TicketTypes *[]dbguild.TicketsType`
53	// / `TicketTypes *[]dbguild.ModmailTicketType`), no un tipo "Body" duplicado:
54	// el struct de dominio YA tiene exactamente la forma que la dashboard envía
55	// (§5.3 del contrato de flujos: el PATCH sustituye el array ENTERO, así que
56	// cada flujo llega completo, con `id`/`created_at`/`updated_at` incluidos).
57	// Los `params` de trigger/condiciones/pasos siguen siendo `map[string]any`
58	// libre — su forma la valida el catálogo compartido, no Go — así que
59	// `DisallowUnknownFields` no los toca; sí rechaza cualquier clave desconocida
60	// a nivel de `ModerationFlow`/`ModerationFlowScope`/etc., que es justo lo que
61	// se quiere.
62	type UpdateModuleModerationBody struct {
63		Enabled            *bool                                 `json:"enabled,omitempty"`
64		CommandMode        *dbguild.ModerationCommandMode        `json:"command_mode,omitempty"`
65		CommandsGlobal     *dbguild.ModerationCommandAccess      `json:"commands_global,omitempty"`
66		Commands           *map[string]dbguild.ModerationCommand `json:"commands,omitempty"`
67		Mute               *dbguild.ModerationMute               `json:"mute,omitempty"`
68		LogChannelID       *string                               `json:"log_channel_id,omitempty"`
69		TrackNativeActions *bool                                 `json:"track_native_actions,omitempty"`
70		Automod            *dbguild.ModerationAutomod            `json:"automod,omitempty"`
71		Protection         *dbguild.ModerationProtection         `json:"protection,omitempty"`
72		Escalation         *dbguild.ModerationEscalation         `json:"escalation,omitempty"`
73		Effects            *dbguild.ModerationEffects            `json:"effects,omitempty"`
74		Raid               *dbguild.ModerationRaid               `json:"raid,omitempty"`
75		Gate               *dbguild.ModerationGate               `json:"gate,omitempty"`
76		Antinuke           *dbguild.ModerationAntinuke           `json:"antinuke,omitempty"`
77		Lockdown           *dbguild.ModerationLockdown           `json:"lockdown,omitempty"`
78		Flows              *[]dbguild.ModerationFlow             `json:"flows,omitempty"`
79	}
80	
81	// ─── PATCH-map enum normalization + "impossible config" rejection ─────────
82	//
83	// `UpdateModuleModerationBody` above only checks JSON SHAPE — unknown keys
84	// (`DisallowUnknownFields`) and JSON type (`encoding/json`) — same as every
85	// other Go module body (see the doc comment above). It does NOT check that an
86	// enum STRING is one of the closed values the Node zod schema allows: nothing
87	// stopped a direct API call (skipping the dashboard's zod entirely) from
88	// persisting `"mute":{"mode":"portal"}`, or a config the bot literally cannot
89	// carry out.
90	//
91	// NormalizeModerationPatch closes that gap on the RAW patch map — the same
92	// map `patchMap` hands to `mongo.MergeDeepJSON` — instead of the typed struct
93	// above: only the map preserves per-leaf KEY PRESENCE, which is what lets an
94	// enum sent as `""` (what an unset dashboard `<select>` serializes as) be
95	// told apart from one the caller deliberately picked.
96	//
97	//   - An enum leaf sent as `""` is NORMALIZED: the key is dropped from the
98	//     patch so the merge leaves the stored value untouched — "no elegido
99	//     todavía", never "configured to nothing".
100	//   - An enum leaf sent as anything else outside its closed set is REJECTED
101	//     (400, zod-shaped): that value is impossible for the bot to act on, the
102	//     same class of error the browser's zod already caught.
103	//   - ONE cross-field impossibility is rejected too: `mute.mode === "role"`
104	//     with no `mute.role_id` in the SAME patch object (mirrors
105	//     `moderationDependencies` in `moderation-schema.ts` — a role-mute the bot
106	//     cannot apply). Every other v3 block deliberately has NO such rule: it
107	//     degrades on its own (see that same comment) — replicating one here
108	//     would be exactly the false guard that was removed from tempvoice.
109	//
110	// Coverage: `command_mode`, `mute.mode` (+ the role dependency), every access
111	// list's `mode` (`commands_global` and each per-command `access`), every
112	// AutoMod rule's `action`, each escalation rule's `action`, every sanction
113	// effect's `policy`, `raid.action`, `gate.action`, and `antinuke.punishment` /
114	// `antinuke.limits[...].punishment`. `flows` is deliberately NOT walked here:
115	// its shape is validated by the shared flow catalog (`flow-schema.ts` /
116	// `validateFlow`), not this schema — duplicating it would risk drifting from
117	// the one source of truth the dashboard already has.
118	//
119	// This does NOT replicate the rest of the zod schema (string max-lengths,
120	// numeric ranges, array sizes): those are Discord-side / cosmetic limits, not
121	// configs the bot is literally unable to execute — out of scope on purpose.
122	func NormalizeModerationPatch(patch map[string]any) *apierrors.CustomError {
123		if verr := normalizeEnumLeaf(patch, "command_mode", moderationCommandModeSet, moderationCommandModeMsg, "command_mode"); verr != nil {
124			return verr
125		}
126		if verr := normalizeModerationMute(patch); verr != nil {
127			return verr
128		}
129		if verr := normalizeModerationCommandsGlobal(patch); verr != nil {
130			return verr
131		}
132		if verr := normalizeModerationCommands(patch); verr != nil {
133			return verr
134		}
135		if verr := normalizeModerationAutomod(patch); verr != nil {
136			return verr
137		}
138		if verr := normalizeModerationEscalation(patch); verr != nil {
139			return verr
140		}
141		if verr := normalizeModerationEffects(patch); verr != nil {
142			return verr
143		}
144		if verr := normalizeEnumObjectLeaf(patch, "raid", "action", moderationRaidActionSet, moderationRaidActionMsg, "raid.action"); verr != nil {
145			return verr
146		}
147		if verr := normalizeEnumObjectLeaf(patch, "gate", "action", moderationGateActionSet, moderationGateActionMsg, "gate.action"); verr != nil {
148			return verr
149		}
150		if verr := normalizeModerationAntinuke(patch); verr != nil {
151			return verr
152		}
153		return nil
154	}
155	
156	// asObject reads `patch[key]` as a nested JSON object. Absent key or a
157	// non-object value (e.g. a client sending `"mute": null`) both return
158	// `false` — nothing to normalize, and not this function's job to reject.
159	func asObject(patch map[string]any, key string) (map[string]any, bool) {
160		v, ok := patch[key]
161		if !ok {
162			return nil, false
163		}
164		m, ok := v.(map[string]any)
165		return m, ok
166	}
167	
168	// normalizeEnumLeaf drops `obj[key]` when it is `""` (see doc above) and
169	// rejects it when it is a non-empty string outside `allowed`. A missing key
170	// or a non-string value (already caught upstream by the strict struct
171	// decode) is left untouched.
172	func normalizeEnumLeaf(obj map[string]any, key string, allowed map[string]bool, msg, property string) *apierrors.CustomError {
173		v, ok := obj[key]
174		if !ok {
175			return nil
176		}
177		s, isStr := v.(string)
178		if !isStr {
179			return nil
180		}
181		if s == "" {
182			delete(obj, key)
183			return nil
184		}
185		if !allowed[s] {
186			return zodItemError(msg, property)
187		}
188		return nil
189	}
190	
191	// normalizeEnumObjectLeaf is normalizeEnumLeaf for a leaf nested one object
192	// down (`patch[objKey][leafKey]`), e.g. `raid.action` / `gate.action`.
193	func normalizeEnumObjectLeaf(patch map[string]any, objKey, leafKey string, allowed map[string]bool, msg, property string) *apierrors.CustomError {
194		obj, ok := asObject(patch, objKey)
195		if !ok {
196			return nil
197		}
198		return normalizeEnumLeaf(obj, leafKey, allowed, msg, property)
199	}
200	
201	const moderationMuteRoleRequiredMsg = `mute.role_id is required when mute.mode is "role"`
202	
203	// normalizeModerationMute normalizes `mute.mode` and rejects the one
204	// cross-field impossibility this module guards: a role-mute with no role.
205	func normalizeModerationMute(patch map[string]any) *apierrors.CustomError {
206		mute, ok := asObject(patch, "mute")
207		if !ok {
208			return nil
209		}
210		if verr := normalizeEnumLeaf(mute, "mode", moderationMuteModeSet, moderationMuteModeMsg, "mute.mode"); verr != nil {
211			return verr
212		}
213		// `mode` was either absent to start with or normalized away above when
214		// empty — either way, this PATCH isn't the one switching to "role", so the
215		// dependency isn't this call's to enforce.
216		mode, sentMode := mute["mode"].(string)
217		if !sentMode || mode != string(dbguild.ModerationMuteModeRole) {
218			return nil
219		}
220		roleID, hasRoleID := mute["role_id"]
221		if !hasRoleID || roleID == nil {
222			return zodItemError(moderationMuteRoleRequiredMsg, "mute.role_id")
223		}
224		if s, isStr := roleID.(string); isStr && s == "" {
225			return zodItemError(moderationMuteRoleRequiredMsg, "mute.role_id")
226		}
227		return nil
228	}
229	
230	// normalizeModerationAccessList normalizes the `mode` enum of the three
231	// access axes (`roles`/`channels`/`categories`) shared by `commands_global`
232	// and every per-command `access` block.
233	func normalizeModerationAccessList(obj map[string]any, prefix string) *apierrors.CustomError {
234		for _, axis := range []string{"roles", "channels", "categories"} {
235			list, ok := obj[axis].(map[string]any)
236			if !ok {
237				continue
238			}
239			property := prefix + "." + axis + ".mode"
240			if verr := normalizeEnumLeaf(list, "mode", moderationAccessModeSet, moderationAccessModeMsg, property); verr != nil {
241				return verr
242			}
243		}
244		return nil
245	}
246	
247	func normalizeModerationCommandsGlobal(patch map[string]any) *apierrors.CustomError {
248		commandsGlobal, ok := asObject(patch, "commands_global")
249		if !ok {
250			return nil
251		}
252		return normalizeModerationAccessList(commandsGlobal, "commands_global")
253	}
254	
255	// normalizeModerationCommands walks the per-command overrides map, each
256	// keyed by command name, and normalizes its `access.<axis>.mode`.
257	func normalizeModerationCommands(patch map[string]any) *apierrors.CustomError {
258		commands, ok := asObject(patch, "commands")
259		if !ok {
260			return nil
261		}
262		for name, item := range commands {
263			cmd, ok := item.(map[string]any)
264			if !ok {
265				continue
266			}
267			access, ok := cmd["access"].(map[string]any)
268			if !ok {
269				continue
270			}
271			if verr := normalizeModerationAccessList(access, "commands."+name+".access"); verr != nil {
272				return verr
273			}
274		}
275		return nil
276	}
277	
278	// moderationAutomodRuleKeys are the nine AutoMod rule blocks, each carrying
279	// its own `action` enum.
280	var moderationAutomodRuleKeys = []string{
281		"mentions", "words", "invites", "spam", "duplicates", "caps", "links", "emojis", "attachments",
282	}
283	
284	func normalizeModerationAutomod(patch map[string]any) *apierrors.CustomError {
285		automod, ok := asObject(patch, "automod")
286		if !ok {
287			return nil
288		}
289		for _, rule := range moderationAutomodRuleKeys {
290			ruleObj, ok := automod[rule].(map[string]any)
291			if !ok {
292				continue
293			}
294			property := "automod." + rule + ".action"
295			if verr := normalizeEnumLeaf(ruleObj, "action", automodActionSet, automodActionMsg, property); verr != nil {
296				return verr
297			}
298		}
299		return nil
300	}
301	
302	func normalizeModerationEscalation(patch map[string]any) *apierrors.CustomError {
303		escalation, ok := asObject(patch, "escalation")
304		if !ok {
305			return nil
306		}
307		rules, ok := escalation["rules"].([]any)
308		if !ok {
309			return nil
310		}
311		for i, item := range rules {
312			rule, ok := item.(map[string]any)
313			if !ok {
314				continue
315			}
316			property := fmt.Sprintf("escalation.rules.%d.action", i)
317			if verr := normalizeEnumLeaf(rule, "action", moderationEscalationActionSet, moderationEscalationActionMsg, property); verr != nil {
318				return verr
319			}
320		}
321		return nil
322	}
323	
324	// moderationEffectKeys are the five sanction-effect blocks, each carrying its
325	// own `policy` enum.
326	var moderationEffectKeys = []string{
327		"voice_disconnect_on_mute", "server_mute_on_mute", "strip_roles_on_mute",
328		"purge_on_ban", "purge_on_kick",
329	}
330	
331	func normalizeModerationEffects(patch map[string]any) *apierrors.CustomError {
332		effects, ok := asObject(patch, "effects")
333		if !ok {
334			return nil
335		}
336		for _, key := range moderationEffectKeys {
337			effect, ok := effects[key].(map[string]any)
338			if !ok {
339				continue
340			}
341			property := "effects." + key + ".policy"
342			if verr := normalizeEnumLeaf(effect, "policy", moderationEffectPolicySet, moderationEffectPolicyMsg, property); verr != nil {
343				return verr
344			}
345		}
346		return nil
347	}
348	
349	// normalizeModerationAntinuke normalizes the block-level `punishment`
350	// (closed set, no `inherit`) and each per-action `limits[...].punishment`
351	// (same set PLUS `inherit`).
352	func normalizeModerationAntinuke(patch map[string]any) *apierrors.CustomError {
353		antinuke, ok := asObject(patch, "antinuke")
354		if !ok {
355			return nil
356		}
357		if verr := normalizeEnumLeaf(antinuke, "punishment", moderationNukePunishmentSet, moderationNukePunishmentMsg, "antinuke.punishment"); verr != nil {
358			return verr
359		}
360		limits, ok := antinuke["limits"].(map[string]any)
361		if !ok {
362			return nil
363		}
364		for action, item := range limits {
365			limit, ok := item.(map[string]any)
366			if !ok {
367				continue
368			}
369			property := "antinuke.limits." + action + ".punishment"
370			if verr := normalizeEnumLeaf(limit, "punishment", moderationNukePunishmentInheritSet, moderationNukePunishmentInheritMsg, property); verr != nil {
371				return verr
372			}
373		}
374		return nil
375	}
376	
377	// ─── enum sets + messages (zod v4 `Invalid option: expected one of ...`) ──
378	
379	var moderationCommandModeSet = map[string]bool{"slash": true, "prefix": true, "both": true}
380	
381	const moderationCommandModeMsg = `Invalid option: expected one of "slash"|"prefix"|"both"`
382	
383	var moderationMuteModeSet = map[string]bool{"auto": true, "timeout": true, "role": true}
384	
385	const moderationMuteModeMsg = `Invalid option: expected one of "auto"|"timeout"|"role"`
386	
387	var moderationAccessModeSet = map[string]bool{"only": true, "all_except": true}
388	
389	const moderationAccessModeMsg = `Invalid option: expected one of "only"|"all_except"`
390	
391	var automodActionSet = map[string]bool{
392		"delete": true, "delete_warn": true, "delete_timeout": true, "delete_kick": true, "delete_ban": true,
393	}
394	
395	const automodActionMsg = `Invalid option: expected one of "delete"|"delete_warn"|"delete_timeout"|"delete_kick"|"delete_ban"`
396	
397	var moderationEscalationActionSet = map[string]bool{
398		"mute": true, "tempmute": true, "kick": true, "tempban": true, "ban": true,
399	}
400	
401	const moderationEscalationActionMsg = `Invalid option: expected one of "mute"|"tempmute"|"kick"|"tempban"|"ban"`
402	
403	var moderationEffectPolicySet = map[string]bool{"always": true, "never": true, "ask": true}
404	
405	const moderationEffectPolicyMsg = `Invalid option: expected one of "always"|"never"|"ask"`
406	
407	var moderationRaidActionSet = map[string]bool{"alert": true, "lockdown": true, "kick": true, "ban": true}
408	
409	const moderationRaidActionMsg = `Invalid option: expected one of "alert"|"lockdown"|"kick"|"ban"`
410	
411	var moderationGateActionSet = map[string]bool{"alert": true, "kick": true, "ban": true, "mute": true}
412	
413	const moderationGateActionMsg = `Invalid option: expected one of "alert"|"kick"|"ban"|"mute"`
414	
415	var moderationNukePunishmentSet = map[string]bool{
416		"alert": true, "strip_roles": true, "kick": true, "ban": true,
417	}
418	
419	const moderationNukePunishmentMsg = `Invalid option: expected one of "alert"|"strip_roles"|"kick"|"ban"`
420	
421	var moderationNukePunishmentInheritSet = map[string]bool{
422		"alert": true, "strip_roles": true, "kick": true, "ban": true, "inherit": true,
423	}
424	
